const body = $input.first().json.body || {};
const limit = body.limit || 500;

// filename:pdf ensures only emails with actual PDF files are fetched.
// This prevents marketing/promotional emails (which match keyword filters
// but only carry HTML or image inline content) from being labeled.
const q = [
  'to:preston@bezantsolutions.com',
  'has:attachment',
  '(filename:pdf OR filename:PDF)',
  '-label:Receipts',
  'after:2026/01/01',
  'before:2027/01/01',
  '(invoice OR "order confirmation" OR "payment confirmation" OR "order receipt" OR receipt OR "your invoice")',
].join(' ');

return [{ json: { query: q, limit } }];

const outputItems = [];

function walkParts(parts, messageId, subject, from) {
  for (const part of (parts || [])) {
    const mime = (part.mimeType || '').toLowerCase();
    const body = part.body || {};
    const attachmentId = body.attachmentId || '';
    const filename = part.filename || '';

    if (attachmentId && filename) {
      const isReceiptFile = (
        mime.includes('pdf') ||
        mime.startsWith('image/') ||
        mime.includes('jpeg') ||
        mime.includes('png') ||
        mime.includes('tiff')
      );
      if (isReceiptFile) {
        outputItems.push({
          json: { messageId, attachmentId, fileName: filename, mimeType: mime, subject, from }
        });
      }
    }

    if (part.parts && part.parts.length > 0) {
      walkParts(part.parts, messageId, subject, from);
    }
  }
}

for (const item of $input.all()) {
  const j = item.json;
  const payload = j.payload || {};
  const headers = payload.headers || [];
  let subject = '';
  let from = '';
  for (const h of headers) {
    if (h.name === 'Subject') subject = h.value;
    if (h.name === 'From')    from    = h.value;
  }
  walkParts(payload.parts, j.id, subject, from);
}

if (outputItems.length === 0) {
  return [{ json: { skip: true, message: 'No PDF/image attachments found' } }];
}
return outputItems;

const results = [];
const allDownloads = $input.all();
const allMeta = $('Has Attachment?').all();

for (let i = 0; i < allDownloads.length; i++) {
  const rawB64 = (allDownloads[i].json.data || '').replace(/-/g, '+').replace(/_/g, '/');
  const meta = (allMeta[i] || { json: {} }).json;
  const fileName = meta.fileName || 'invoice.pdf';
  const mimeType = meta.mimeType || 'application/pdf';

  results.push({
    json: {
      emailId: meta.messageId || '',
      subject: meta.subject || '',
      from: meta.from || '',
      fileName,
      mimeType
    },
    binary: {
      file: {
        data: rawB64,
        mimeType,
        fileName,
        fileExtension: fileName.split('.').pop() || 'pdf'
      }
    }
  });
}

return results;
